<?php// dashboard/api/limpiar_puntos.phpheader('Content-Type: application/json');header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: POST, OPTIONS');if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {    http_response_code(200);    exit;}$paths = ['../../config.php', '../config.php', 'config.php', '../../../config.php'];foreach ($paths as $path) {    if (file_exists($path)) {        require_once $path;        break;    }}$data = json_decode(file_get_contents('php://input'), true);if (!$data || empty($data['partida_id'])) {    echo json_encode(['success' => false, 'error' => 'ID de partida requerido']);    exit;}try {    // Limpiar todos los puntos parciales de la partida    $stmt = $pdo->prepare("DELETE FROM puntos_en_vivo WHERE partida_id = ?");    $stmt->execute([$data['partida_id']]);        echo json_encode([        'success' => true,        'message' => 'Puntos limpiados correctamente'    ]);    } catch(Exception $e) {    error_log("Error en limpiar_puntos.php: " . $e->getMessage());    echo json_encode([        'success' => false,        'error' => $e->getMessage()    ]);}?>